        let triggered = Arc::new(AtomicUsize::new(0));
        let prevented_copy = Arc::clone(&prevented);
        let triggered_copy = Arc::clone(&triggered);
        handle_main_close_requested(
            move || {
                prevented_copy.fetch_add(1, Ordering::AcqRel);
