        let mut profiles = (0..ACTIVE_FORWARD_LIMIT + 2)
            .map(auto_start_profile)
            .collect::<Vec<_>>();
        profiles.reverse();
        let (admitted, skipped) = partition_auto_start_candidates(profiles);
        assert_eq!(admitted.len(), ACTIVE_FORWARD_LIMIT);
